        '{"term": "hungry", "meaning": "hambriento", "de": "hungrig", "ex": "I am hungry. Let''s eat!", "pron": "/hán-gri/", "pron_de": "/HUNG-riç/"}'::jsonb,
        '{"term": "thirsty", "meaning": "sediento", "de": "durstig", "ex": "Are you thirsty? Here is some water.", "pron": "/zérs-ti/", "pron_de": "/DURS-tiç/"}'::jsonb
    ];
BEGIN
    SELECT uuid INTO v_path_id FROM path WHERE source_language = 'en' LIMIT 1;
    DELETE FROM deck WHERE step_order = 245 AND path_uuid = v_path_id;
    INSERT INTO deck (path_uuid, step_order, source_language, type) VALUES (v_path_id, 245, 'en', 'deck') RETURNING uuid INTO v_deck_id;
    INSERT INTO deck_translation (deck_uuid, language, title) VALUES (v_deck_id, 'es', 'Comida y Bebida');
    INSERT INTO deck_translation (deck_uuid, language, title) VALUES (v_deck_id, 'de', 'Essen und Trinken');
    FOREACH card IN ARRAY v_cards LOOP
        SELECT get_or_create_word(card->>'term', 'en', card->>'ex') INTO v_word_id;
        INSERT INTO word_translation (word_uuid, language, meaning, pronunciation) VALUES (v_word_id, 'es', jsonb_build_object('translation', card->>'meaning'), card->>'pron') ON CONFLICT DO NOTHING;
        INSERT INTO word_translation (word_uuid, language, meaning, pronunciation) VALUES (v_word_id, 'de', jsonb_build_object('translation', card->>'de'), card->>'pron_de') ON CONFLICT DO NOTHING;
        INSERT INTO deck_words (deck_uuid, word_uuid) VALUES (v_deck_id, v_word_id) ON CONFLICT DO NOTHING;
    END LOOP;
END;
$seed$;
